/bin/bash -c "python - <<'PY'
import numpy as np
X=np.array([[0,1],[1,0]],complex)
Y=np.array([[0,-1j],[1j,0]],complex)
I=np.eye(2)
def op(n,site,A):
    out=np.array([[1]],complex)
    for j in range(n): out=np.kron(out,A if j==site else I)
    return out
def deg(vals):
    vals=np.linalg.eigvalsh(vals)
    return vals[0], np.sum(np.isclose(vals,vals[0],atol=1e-8)), vals[:12]
for n in [2,4,6,8,10]:
    H=np.zeros((2**n,2**n),complex)
    for i in range(1,n//2+1):
        H-=op(n,2*i-2,X)@op(n,2*i-1,X)
        if 2*i < n:
            H-=op(n,2*i-1,Y)@op(n,2*i,Y)
    print(n,deg(H))
PY"

